"""Core feature-selection optimizer generated by an LLM."""

import math

import numpy as np
from sklearn.ensemble import ExtraTreesRegressor


class GeneratedOptimizer:
    """Surrogate-assisted adaptive binary evolutionary optimizer.

    The optimizer starts with a diversity-aware design, then trains an Extra Trees
    surrogate. A binary evolutionary candidate pool is ranked by a lower-confidence
    acquisition score and selected greedily for batch diversity.
    """

    def __init__(self, bounds, variable_types, budget, seed):
        self.bounds = list(bounds)
        self.variable_types = list(variable_types)
        self.dimension = len(self.bounds)
        self.budget = int(budget)
        self.rng = np.random.default_rng(int(seed))
        if self.dimension <= 0:
            raise ValueError("At least one variable is required.")
        if len(self.variable_types) != self.dimension:
            raise ValueError("variable_types must match bounds.")

        self.X = []
        self.y = []
        self.pending = set()
        self.evaluated = set()
        self.best_x = None
        self.best_y = float("inf")
        self.stagnation = 0
        self.initial_size = min(self.budget, max(8, int(2 * math.sqrt(self.dimension))))

    @staticmethod
    def _key(x):
        return tuple(int(v) for v in np.asarray(x).reshape(-1))

    def _repair(self, x):
        x = (np.asarray(x, dtype=float).reshape(-1) >= 0.5).astype(np.int8)
        if not x.any():
            x[self.rng.integers(0, self.dimension)] = 1
        return x

    def _unseen(self, x, local):
        key = self._key(x)
        return key not in self.evaluated and key not in self.pending and key not in local

    def _random_mask(self):
        # Vary subset density so the initial design covers sparse and dense regions.
        probability = float(self.rng.uniform(0.15, 0.85))
        return self._repair(self.rng.random(self.dimension) < probability)

    def _initial_candidates(self, n_points):
        chosen = []
        local = set()
        attempts = 0
        while len(chosen) < n_points and attempts < 4000:
            pool = [self._random_mask() for _ in range(40)]
            pool = [x for x in pool if self._unseen(x, local)]
            if not pool:
                attempts += 40
                continue
            if self.X or chosen:
                references = np.asarray(self.X + chosen, dtype=np.int8)
                distances = [np.min(np.mean(references != x, axis=1)) for x in pool]
                x = pool[int(np.argmax(distances))]
            else:
                x = pool[0]
            key = self._key(x)
            local.add(key)
            chosen.append(x)
            attempts += 40
        return chosen

    def _evolutionary_pool(self, size):
        X = np.asarray(self.X, dtype=np.int8)
        y = np.asarray(self.y, dtype=float)
        order = np.argsort(y)
        elite_count = min(len(X), max(3, int(math.ceil(len(X) * 0.25))))
        elites = X[order[:elite_count]]
        pool = []
        local = set()

        # Increase mutation after stagnation; retain a low floor for local refinement.
        mutation = min(0.35, max(1.0 / self.dimension, 0.02) * (1.0 + 0.35 * self.stagnation))
        attempts = 0
        while len(pool) < size and attempts < size * 12:
            attempts += 1
            if self.rng.random() < 0.22:
                child = self._random_mask()
            else:
                a = elites[self.rng.integers(0, elite_count)]
                b = X[self.rng.integers(0, len(X))]
                crossover = self.rng.random(self.dimension) < 0.5
                child = np.where(crossover, a, b).astype(np.int8)
                flips = self.rng.random(self.dimension) < mutation
                if not flips.any():
                    flips[self.rng.integers(0, self.dimension)] = True
                child = np.logical_xor(child, flips).astype(np.int8)
                child = self._repair(child)
            key = self._key(child)
            if self._unseen(child, local):
                local.add(key)
                pool.append(child)
        return np.asarray(pool, dtype=np.int8)

    def _surrogate_select(self, n_points):
        pool_size = max(500, 35 * self.dimension)
        pool = self._evolutionary_pool(pool_size)
        if len(pool) == 0:
            return self._initial_candidates(n_points)

        X = np.asarray(self.X, dtype=float)
        y = np.asarray(self.y, dtype=float)
        model = ExtraTreesRegressor(
            n_estimators=120,
            min_samples_leaf=1,
            max_features="sqrt",
            bootstrap=True,
            random_state=int(self.rng.integers(0, 2**31 - 1)),
            n_jobs=1,
        )
        model.fit(X, y)
        tree_predictions = np.vstack([tree.predict(pool) for tree in model.estimators_])
        mean = tree_predictions.mean(axis=0)
        uncertainty = tree_predictions.std(axis=0)

        mean_scale = np.std(mean) + 1e-12
        uncertainty_scale = np.std(uncertainty) + 1e-12
        progress = len(self.y) / max(1, self.budget)
        beta = max(0.25, 1.4 * (1.0 - progress) + 0.15 * self.stagnation)
        acquisition = (mean - np.min(mean)) / mean_scale
        acquisition -= beta * (uncertainty - np.min(uncertainty)) / uncertainty_scale

        chosen = []
        available = np.ones(len(pool), dtype=bool)
        for _ in range(min(n_points, len(pool))):
            indices = np.flatnonzero(available)
            if len(indices) == 0:
                break
            scores = acquisition[indices].copy()
            if chosen:
                selected = np.asarray(chosen, dtype=np.int8)
                diversity = np.min(np.mean(pool[indices, None, :] != selected[None, :, :], axis=2), axis=1)
                scores -= 0.25 * diversity
            pick = int(indices[int(np.argmin(scores))])
            chosen.append(pool[pick])
            available[pick] = False
        return chosen

    def ask(self, n_points):
        remaining = self.budget - len(self.y) - len(self.pending)
        n_points = min(max(0, int(n_points)), max(0, remaining))
        if n_points == 0:
            return np.empty((0, self.dimension), dtype=np.int8)

        if len(self.y) < self.initial_size:
            points = self._initial_candidates(n_points)
        else:
            points = self._surrogate_select(n_points)
        if len(points) < n_points:
            extra = self._initial_candidates(n_points - len(points))
            points.extend(extra)

        clean = []
        for x in points[:n_points]:
            x = self._repair(x)
            key = self._key(x)
            if key not in self.pending and key not in self.evaluated:
                self.pending.add(key)
                clean.append(x)
        return np.asarray(clean, dtype=np.int8)

    def tell(self, X, y):
        X = np.asarray(X, dtype=float)
        y = np.asarray(y, dtype=float).reshape(-1)
        if X.ndim != 2 or X.shape[1] != self.dimension or X.shape[0] != y.size:
            raise ValueError("X and y have incompatible shapes.")

        old_best = self.best_y
        for row, value in zip(X, y):
            x = self._repair(row)
            key = self._key(x)
            self.pending.discard(key)
            if key in self.evaluated:
                continue
            self.evaluated.add(key)
            self.X.append(x)
            self.y.append(float(value))
            if float(value) < self.best_y:
                self.best_y = float(value)
                self.best_x = x.copy()
        self.stagnation = 0 if self.best_y < old_best - 1e-12 else self.stagnation + 1

    def get_best(self):
        if self.best_x is None:
            return None, float("inf")
        return self.best_x.copy(), float(self.best_y)

